package io.github.deepseekbridge;
import android.app.Application;import android.content.Context;import android.graphics.*;import org.json.*;import java.io.*;import java.nio.file.Files;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,33},manifest=Config.NONE,application=Application.class)
public class ChatMediaTest {
 Context context;ChatMedia media;
 @Before public void setup(){context=RuntimeEnvironment.getApplication();media=new ChatMedia(context);}
 @Test public void appCaptureHasARealReusableProjectPathAndCacheIsRemoved()throws Exception{
  StudioRuntime runtime=new StudioRuntime(context,event->{});File capture=new File(context.getCacheDir(),"app-capture.png");Files.copy(new File("../../js/ui/logo.png").toPath(),capture.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);
  try{byte[] original=Files.readAllBytes(capture.toPath());JSONObject result=runtime.attachAppCapture("p-app-capture",new JSONObject().put("ok",true).put("captureFile",capture.getAbsolutePath()));assertFalse(result.has("captureFile"));assertFalse(capture.exists());JSONObject attachment=result.getJSONObject("attachment");assertTrue(attachment.getBoolean("image"));assertTrue(attachment.getString("path").startsWith("captures/app-"));File saved=runtime.files.resolve("p-app-capture",attachment.getString("path"));assertArrayEquals(original,Files.readAllBytes(saved.toPath()));JSONObject reopened=runtime.media.attach(saved,"p-app-capture",attachment.getString("path"));assertEquals(attachment.getString("id"),reopened.getString("id"));}finally{runtime.close();}
 }
 @Test public void mcpImageIsSavedAsARealProjectFileAndDecodedIntoImmutableChatPixels()throws Exception{StudioRuntime runtime=new StudioRuntime(context,event->{});java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);final boolean[] ok={false};final Object[] value={null};String encoded=android.util.Base64.encodeToString(Files.readAllBytes(new File("../../js/ui/logo.png").toPath()),android.util.Base64.NO_WRAP);try{runtime.request("media.mcp",new JSONObject().put("project","p-mcp-image").put("mime","image/png").put("data",encoded),(success,result)->{ok[0]=success;value[0]=result;done.countDown();});assertTrue(done.await(5,java.util.concurrent.TimeUnit.SECONDS));assertTrue(String.valueOf(value[0]),ok[0]);JSONObject attachment=(JSONObject)value[0];assertTrue(attachment.getBoolean("image"));assertTrue(runtime.files.resolve("p-mcp-image",attachment.getString("path")).isFile());assertTrue(runtime.media.data(attachment.getString("id")).startsWith("data:image/jpeg;base64,"));}finally{runtime.close();}}
 @Test public void imageCopiesRemainStableAfterTheProjectImageChanges()throws Exception{
  File source=new File(context.getCacheDir(),"photo.png");Files.copy(new File("../../js/ui/logo.png").toPath(),source.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);JSONObject attachment=media.attach(source,"p-fixture","photo.png");assertTrue(attachment.toString(),attachment.getBoolean("image"));String id=attachment.getString("id"),before=media.data(id);assertTrue(before.startsWith("data:image/jpeg;base64,"));Files.write(source.toPath(),new byte[]{1,2,3});assertEquals(before,media.data(id));assertEquals("https://bridge.local/chat-media/"+id,attachment.getString("url"));
 }
 @Test public void ordinaryFilesStayFileAttachmentsAndDoNotBecomeFakeImages()throws Exception{File source=new File(context.getCacheDir(),"report.txt");Files.write(source.toPath(),"a plain report".getBytes("UTF-8"));JSONObject attachment=media.attach(source,"p-fixture","report.txt");assertFalse(attachment.getBoolean("image"));assertEquals(14,attachment.getLong("bytes"));assertFalse(attachment.has("id"));}
 @Test public void mediaIdsCannotReadOtherPrivateFiles()throws Exception{for(String id:new String[]{"../secret","../../preferences.xml","","file:///secret"})try{media.file(id);fail("unsafe media ID accepted");}catch(IOException expected){}try{media.data(String.join("",java.util.Collections.nCopies(64,"f")));fail("missing image accepted");}catch(IOException expected){}}
}
